/**
 * Emoji list and search. Data is generated by scripts/build.ts and loaded on demand: the list
 * with English names (~45 KB gzipped) and, per language, CLDR keywords (~25-50 KB gzipped).
 */

export interface Emoji {
  char: string;
  /** Index into EmojiData.groups. */
  group: number;
  /** English CLDR name, e.g. "grinning face". */
  name: string;
  /** English keywords joined with "|". */
  keywords: string;
  /** Light to dark skin-tone variants, when the emoji has all five. */
  skins?: readonly string[];
}

export interface EmojiData {
  version: string;
  groups: readonly string[];
  emoji: readonly Emoji[];
}

/** Emoji -> "name|keyword|keyword..." in one language. */
export type Annotations = Readonly<Record<string, string>>;

type Row = [string, number, string, string, string[]?];

export async function loadEmoji(): Promise<EmojiData> {
  const raw = (await import("../data/emoji.json")).default as {
    version: string;
    groups: string[];
    emoji: Row[];
  };
  return {
    version: raw.version,
    groups: raw.groups,
    emoji: raw.emoji.map(([char, group, name, keywords, skins]) =>
      skins ? { char, group, name, keywords, skins } : { char, group, name, keywords },
    ),
  };
}

const ANNOTATIONS: Record<string, () => Promise<{ default: unknown }>> = {
  ur: () => import("../data/ur.json"),
  ar: () => import("../data/ar.json"),
  fa: () => import("../data/fa.json"),
  ps: () => import("../data/ps.json"),
  sd: () => import("../data/sd.json"),
  "pa-Arab": () => import("../data/pa-Arab.json"),
  hi: () => import("../data/hi.json"),
  bn: () => import("../data/bn.json"),
};

/** Languages without CLDR emoji keywords whose speakers read Urdu. */
const URDU_FALLBACK = new Set(["skr", "bal", "ks"]);

/** The keyword set for a language tag (e.g. "ur", "pa-Arab"), or null if there is none. */
export function annotationLocale(lang: string): string | null {
  if (lang in ANNOTATIONS) return lang;
  const base = lang.split("-")[0]!;
  if (URDU_FALLBACK.has(base)) return "ur";
  return base in ANNOTATIONS ? base : null;
}

export async function loadAnnotations(locale: string): Promise<Annotations> {
  const load = ANNOTATIONS[locale];
  if (!load) throw new Error(`No emoji keywords for ${locale}`);
  return (await load()).default as Annotations;
}

/** Skin tones: 0 is the default yellow, 1-5 light to dark. */
export const SKIN_TONES = [
  "Default",
  "Light",
  "Medium-light",
  "Medium",
  "Medium-dark",
  "Dark",
] as const;

export function withSkin(emoji: Emoji, tone: number): string {
  return (tone > 0 && emoji.skins?.[tone - 1]) || emoji.char;
}

/**
 * Fold text for matching: lower case, no Latin accents or Arabic vowel marks, and one form for
 * letters that Arabic, Persian and Urdu keyboards type differently (ي/ی, ك/ک, ه/ہ).
 */
export function normalize(text: string): string {
  return text
    .normalize("NFD")
    .toLowerCase()
    .replace(/[̀-ًͯ-ٰٟـ]/g, "")
    .replace(/[يى]/g, "ی")
    .replace(/ك/g, "ک")
    .replace(/ه/g, "ہ")
    .replace(/[’‘]/g, "'")
    .normalize("NFC");
}

const SPLIT = /[\s|:,()“”"!?.،؛۔]+/u;
const words = (text: string) => normalize(text).split(SPLIT).filter(Boolean);

interface IndexEntry {
  emoji: Emoji;
  names: string[];
  nameWords: Set<string>;
  /** Words in the shortest name, to prefer "red heart" over "smiling face with heart-eyes". */
  nameLength: number;
  keywords: Set<string>;
}

export interface EmojiIndex {
  entries: readonly IndexEntry[];
}

export function buildIndex(data: EmojiData, native?: Annotations): EmojiIndex {
  return {
    entries: data.emoji.map((emoji) => {
      const [nativeName, ...nativeKeywords] = native?.[emoji.char]?.split("|") ?? [];
      const names = [emoji.name, nativeName].filter((n): n is string => !!n).map(normalize);
      return {
        emoji,
        names,
        nameWords: new Set(names.flatMap(words)),
        nameLength: Math.min(...names.map((n) => words(n).length)),
        keywords: new Set([...emoji.keywords.split("|"), ...nativeKeywords].flatMap(words)),
      };
    }),
  };
}

/**
 * Emoji whose names or keywords (English or the page language) contain every word of the
 * query as a word prefix, best first: exact name, name prefix, then name words before keywords,
 * then names the query covers more of.
 */
export function searchEmoji(index: EmojiIndex, query: string, limit = 150): Emoji[] {
  const q = normalize(query).trim();
  const tokens = q.split(SPLIT).filter(Boolean);
  if (!tokens.length) return [];

  const scored: { emoji: Emoji; score: number; order: number }[] = [];
  index.entries.forEach((entry, order) => {
    let score = 0;
    for (const token of tokens) {
      let best = 0;
      for (const w of entry.nameWords)
        best = Math.max(best, w === token ? 30 : w.startsWith(token) ? 20 : 0);
      if (best < 30) {
        for (const w of entry.keywords) {
          best = Math.max(best, w === token ? 15 : w.startsWith(token) ? 8 : 0);
          if (best === 30) break;
        }
      }
      if (!best) return;
      score += best;
    }
    if (entry.names.includes(q)) score += 1000;
    else if (entry.names.some((n) => n.startsWith(q))) score += 300;
    score += Math.min(10, Math.round((10 * tokens.length) / Math.max(1, entry.nameLength)));
    scored.push({ emoji: entry.emoji, score, order });
  });
  return scored
    .sort((a, b) => b.score - a.score || a.order - b.order)
    .slice(0, limit)
    .map((s) => s.emoji);
}
